export type CatalogSnapshotResponse = {
    /**
     * ISO-8601 UTC capture time
     */
    generatedAt: string;
    warehouseId: string;
    skus: Array<CatalogSnapshotSkuDto>;
    /**
     * The warehouse's open POs with their lines
     */
    openPurchaseOrders: Array<CatalogSnapshotPoDto>;
    /**
     * Story 21-6 (additive): the warehouse's open advance shipment notices (announced or partially received) with per-line announced / received / open — receiving books against them exactly as against a PO
     */
    openAsns: Array<CatalogSnapshotAsnDto>;
    /**
     * Story 3.5 (additive): every bin of the warehouse — blocked/system bins included so the device can reject a scan against them pre-queue
     */
    bins: Array<PutawayBinDto>;
    /**
     * Story 3.5 (additive): the derived putaway tasks with the capacity-only suggestions (advisory — the server re-gates at placement)
     */
    putawayTasks: Array<PutawayTaskDto>;
    /**
     * Story 4.3 (additive): the pick tasks of every ready picklist on a released wave, in walk order (the bin/batch each names is advisory — the server re-derives both at pick time)
     */
    pickTasks: Array<PickTaskDto>;
    /**
     * Story 10.7 (additive): the packable orders' per-SKU picked totals — the dataset the bench pre-verifies its scan against, offline. Mirrors the pack command's own verification query (picks grouped by (order, sku)) and its completeness guards (accepted, ≥1 pick line, none planned, not all cancelled)
     */
    packTasks: Array<CatalogPackTaskDto>;
    /**
     * Story 10.7 (additive): every ACTIVE handling unit of the warehouse (id + skuId) — the labels a catch-weight bench scan resolves against, offline. Active-only self-prunes (units flip to packed at pack)
     */
    handlingUnits: Array<CatalogHandlingUnitDto>;
    /**
     * Story 5-1 (additive): the in-transit transfers TO this warehouse — the Transfer inbox tasks whose inbound confirm the operator executes (one confirm completes the whole order)
     */
    transferTasks: Array<CatalogTransferTaskDto>;
    /**
     * Story 5-3 (additive): the STORED pending count tasks of this warehouse — the Count inbox tasks whose submit the operator executes (every task line must be counted; 0 is a valid explicit count). The expectations were FROZEN at task start and are read here, never recomputed
     */
    countTasks: Array<CatalogCountTaskDto>;
    /**
     * Story 13-2 (additive): the warehouse's return authorizations that can still receive (open or partially received) — the handheld receives returned units against them offline, grading each unit; units not on an authorization are queued for review, never refused on the device
     */
    openReturns: Array<CatalogOpenReturnDto>;
    /**
     * Story 1-1 (additive): every client referenced by a SKU or an open document of the snapshot — the names the device shows when a scan belongs to another client, and the blind receipt's client picker. A snapshot WITHOUT this field (an older server) puts the device in legacy mode: no picker, no clientId sent
     */
    clients: Array<CatalogSnapshotClientDto>;
    /**
     * Story 2-3a (additive): the warehouse's open gate-ins — not gated out, gated in within the last 7 days, at most 200, newest first (decision 15). The dock records their unload and receives against them. An older server omits it
     */
    openGateIns: Array<CatalogOpenGateInDto>;
    /**
     * Story 2-4a (additive): the damage reason vocabulary — the handheld shows its Damaged control only when the snapshot carries it (an older server omits it), and refuses to confirm a draft holding damage against a snapshot without it
     */
    receiptDamageReasons: Array<'crushed' | 'wet' | 'torn-packaging' | 'broken' | 'leaking' | 'pest' | 'other'>;
    /**
     * Story 2-4a (additive): the short reason vocabulary — the Short control's gate, as receiptDamageReasons
     */
    receiptShortReasons: Array<'not-shipped' | 'short-packed' | 'lost-in-transit' | 'other'>;
    /**
     * Story 3-1 (additive): the bin-to-bin move's reason vocabulary, in order — the handheld's reason chips. A reason with noteRequired needs a note (up to 200 characters). An older server omits it, and the handheld then offers no Move stock
     */
    moveReasons: Array<CatalogMoveReasonDto>;
    /**
     * Story 3-2b (additive): the stock adjustment's reason vocabulary with labels, in order — the handheld's Adjust reason chips (every reason needs the note the adjustment always carries). An older server omits it, and the handheld then offers no Adjust
     */
    adjustReasons: Array<CatalogAdjustReasonDto>;
};

